ALTER TABLE pricing_plans ADD COLUMN IF NOT EXISTS description VARCHAR(1000) NULL;
ALTER TABLE pricing_plans ADD COLUMN IF NOT EXISTS price DECIMAL(15,2) NOT NULL DEFAULT 0;
ALTER TABLE pricing_plans ADD COLUMN IF NOT EXISTS is_active BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE pricing_plans ADD COLUMN IF NOT EXISTS updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6);

CREATE TABLE IF NOT EXISTS payment_gateways (
  id CHAR(36) PRIMARY KEY, gateway_name VARCHAR(160) NOT NULL UNIQUE, is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_by CHAR(36) NULL, updated_by CHAR(36) NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY (updated_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payment_methods (
  id CHAR(36) PRIMARY KEY, method_name VARCHAR(160) NOT NULL, method_code VARCHAR(50) NOT NULL UNIQUE, is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_by CHAR(36) NULL, updated_by CHAR(36) NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY (updated_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payment_method_options (
  id CHAR(36) PRIMARY KEY, method_id CHAR(36) NOT NULL, option_name VARCHAR(160) NOT NULL, option_code VARCHAR(50) NOT NULL UNIQUE, is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_by CHAR(36) NULL, updated_by CHAR(36) NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  FOREIGN KEY (method_id) REFERENCES payment_methods(id), FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY (updated_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS gateway_method_mappings (
  id CHAR(36) PRIMARY KEY, gateway_id CHAR(36) NOT NULL, method_id CHAR(36) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_by CHAR(36) NULL, updated_by CHAR(36) NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  UNIQUE KEY uq_gateway_method (gateway_id, method_id), FOREIGN KEY (gateway_id) REFERENCES payment_gateways(id), FOREIGN KEY (method_id) REFERENCES payment_methods(id), FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY (updated_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS plan_gateway_role_configs (
  id CHAR(36) PRIMARY KEY, plan_id CHAR(36) NOT NULL, gateway_id CHAR(36) NOT NULL, role_id BIGINT UNSIGNED NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_by CHAR(36) NULL, updated_by CHAR(36) NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  UNIQUE KEY uq_plan_gateway_role (plan_id, gateway_id, role_id), FOREIGN KEY (plan_id) REFERENCES pricing_plans(id), FOREIGN KEY (gateway_id) REFERENCES payment_gateways(id), FOREIGN KEY (role_id) REFERENCES roles(id), FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY (updated_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS plan_commissions (
  id CHAR(36) PRIMARY KEY, plan_config_id CHAR(36) NOT NULL, method_id CHAR(36) NOT NULL, method_option_id CHAR(36) NULL, commission_rate DECIMAL(9,4) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_by CHAR(36) NULL, updated_by CHAR(36) NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  UNIQUE KEY uq_plan_commission (plan_config_id, method_id, method_option_id), CHECK (commission_rate > 0), FOREIGN KEY (plan_config_id) REFERENCES plan_gateway_role_configs(id), FOREIGN KEY (method_id) REFERENCES payment_methods(id), FOREIGN KEY (method_option_id) REFERENCES payment_method_options(id), FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY (updated_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB;
